import type { SectionCategory, StructureInfo } from './types'

/** Compact constructor: category, names (en / uz / Latin), info, lesion, 3D concept. */
export function S(
  cat: SectionCategory,
  en: string,
  uz: string,
  la: string | undefined,
  infoEn: string,
  infoUz: string,
  lesionEn?: string,
  lesionUz?: string,
  part?: string,
): StructureInfo {
  return {
    cat,
    name: { en, uz, la },
    info: { en: infoEn, uz: infoUz },
    lesion: lesionEn ? { en: lesionEn, uz: lesionUz ?? lesionEn } : undefined,
    part,
  }
}

